  if (cached && Date.now() - Date.parse(cached.fetchedAt) < FRESH_MS) return Response.json(cached);

  try {
    const { character, raw } = await crawlCharacter(name);
    upsertCharacter(character, raw);
    return Response.json(character);
  } catch (e) {
