test("ratioOf picks the stat matching the boss basis", () => {
  assert.equal(ratioOf(stats, { statBasis: "300", cut: 100_000 }), 0.5);
  assert.equal(ratioOf(stats, { statBasis: "380", cut: 100_000 }), 0.4);
